def esc(x): return html.escape(str(x or ''))

def linkify(x):
    safe=esc(x)
    pattern=r'(?<!["\'=])(https?://[^\s<]+|www\.[^\s<]+)'
    def repl(m):
        raw=m.group(0)
        trailing=''
        while raw and raw[-1] in '.,;:!?)]}':
            trailing=raw[-1]+trailing
            raw=raw[:-1]
        href=raw if raw.startswith(('http://','https://')) else 'https://'+raw
        return f'<a href="{esc(href)}" target="_blank" rel="noopener noreferrer">{esc(raw)}</a>'+esc(trailing)
    return re.sub(pattern,repl,safe)

NAV_JS='''<script>(function(){
var top=document.querySelector('.top.has-nav');if(!top)return;
var nav=top.querySelector('nav'),btn=top.querySelector('.navtoggle'),drops=nav.querySelectorAll('details.navdrop');
var mobile=window.matchMedia('(max-width:1180px)');
function closeDrops(except){for(var i=0;i<drops.length;i++){if(drops[i]!==except)drops[i].open=false;}}
function setNav(open){top.classList.toggle('nav-open',open);btn.setAttribute('aria-expanded',open?'true':'false');btn.textContent=open?'✕ Κλείσιμο':'☰ Μενού';if(!open)closeDrops();}
function vpBox(){var v=window.visualViewport,cw=document.documentElement.clientWidth;if(v)return [v.offsetLeft,Math.min(cw,v.offsetLeft+v.width)];return [0,cw];}
function place(d){var m=d.querySelector('.navdrop-menu');if(!m)return;m.classList.remove('align-right');m.style.left='';m.style.right='';if(mobile.matches)return;var b=vpBox(),g=8,lo=b[0]+g,hi=b[1]-g,r=m.getBoundingClientRect();if(r.right>hi){m.classList.add('align-right');r=m.getBoundingClientRect();}if(r.left<lo||r.right>hi){var p=d.getBoundingClientRect(),x=Math.max(lo,Math.min(r.left,hi-r.width));m.style.right='auto';m.style.left=(x-p.left)+'px';}}
btn.addEventListener('click',function(){setNav(!top.classList.contains('nav-open'));});
for(var i=0;i<drops.length;i++){drops[i].addEventListener('toggle',function(e){var d=e.target;if(d.open){closeDrops(d);place(d);if(mobile.matches)setTimeout(function(){d.scrollIntoView({block:'nearest',behavior:'smooth'});},0);}});}
document.addEventListener('pointerdown',function(e){if(!top.contains(e.target)){closeDrops();if(mobile.matches)setNav(false);}});
document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeDrops();setNav(false);if(mobile.matches)btn.focus();}});
var onChange=function(){if(!mobile.matches)setNav(false);closeDrops();};
function replace(){for(var i=0;i<drops.length;i++)if(drops[i].open)place(drops[i]);}window.addEventListener('resize',replace);if(window.visualViewport)window.visualViewport.addEventListener('resize',replace);
if(mobile.addEventListener)mobile.addEventListener('change',onChange);else if(mobile.addListener)mobile.addListener(onChange);
window.addEventListener('pageshow',function(){setNav(false);});
})();</script>'''

TABLE_JS='''<script>(function(){
var ts=document.querySelectorAll('main.wrap table');
for(var t=0;t<ts.length;t++){var tb=ts[t];if(tb.closest('.paper'))continue;
var rows=tb.rows;if(!rows.length)continue;var head=rows[0],hc=head.cells,labels=[],ok=hc.length>1;
for(var i=0;i<hc.length;i++){if(hc[i].tagName!=='TH'){ok=false;break;}labels.push(hc[i].textContent.trim());}
if(!ok)continue;head.classList.add('stack-head');
for(var r=1;r<rows.length;r++){var col=0,cs=rows[r].cells;for(var c=0;c<cs.length;c++){var td=cs[c],span=td.colSpan||1,lab=labels[col]||'';
if(span>1||!lab){td.classList.add('nolabel');}else{td.setAttribute('data-label',lab);var v=document.createElement('div');v.className='cell-v';while(td.firstChild)v.appendChild(td.firstChild);td.appendChild(v);if(/Ενέργειες|Πράξη/.test(lab))td.classList.add('actions-cell');}col+=span;}}
tb.classList.add('stack');}
if(window.matchMedia('(max-width:700px)').matches){var fs=document.querySelectorAll('details.fold[data-mobile-closed]');for(var f=0;f<fs.length;f++)fs[f].open=false;}
})();</script>'''

def _notif_html(u):
    f=globals().get('notifications_banner')
    try:return f(u) if (u and f) else ''
    except Exception:return ''

def page(body,user=None,title='Μεγάλη Γραμματεία'):
    nav=''
    if user:
        actor_note=''
        actor_link=''
        if user.get('email','').lower() in {SHARED_SECRETARIAT_EMAIL,PRIMARY_ADMIN_EMAIL} and user.get('_actor') in ACTOR_LABELS:
            actor_note=f''' <span class="actor-pill">Υπογράφων: {esc(ACTOR_LABELS[user['_actor']])}</span>'''
            actor_link='<a href="/identity">Αλλαγή Υπογράφοντος</a>'
        nav=f'''<header class="top has-nav"><div class="brand"><b>Μεγάλη Γραμματεία · ΕΜΣΤΕ</b>{actor_note}</div><button type="button" class="navtoggle" aria-expanded="false" aria-controls="mainnav">☰ Μενού</button><nav id="mainnav" aria-label="Κύριο μενού"><a href="/">Αρχική</a><details class="navdrop letters"><summary>Επιστολές <span class="caret">▾</span></summary><div class="navdrop-menu"><a href="/new">+ Νέα Επιστολή</a><a href="/archive">Αρχείο Επιστολών</a>{'<div class="navdrop-sep"></div><a href="/templates">Πρότυπα Επιστολών</a>' if user['role']=='admin' else ''}</div></details><details class="navdrop"><summary>Διατάγματα <span class="caret">▾</span></summary><div class="navdrop-menu"><a href="/decrees/new">+ Νέο Διάταγμα</a><a href="/decrees/archive">Αρχείο Διαταγμάτων</a><div class="navdrop-sep"></div><a href="/decrees/new?action=appoint">ΔΙΟΡΙΖΟΜΕΝ</a><a href="/decrees/new?action=award">ΑΠΟΝΕΜΕΙ</a><a href="/decrees/new?action=service_award">ΕΥΑΡΕΣΤΟΥΜΕΘΑ ΝΑ ΑΠΟΝΕΙΜΩΜΕΝ</a></div></details>{'<details class="navdrop"><summary>Επισκέψεις <span class="caret">▾</span></summary><div class="navdrop-menu"><a href="/visits">Ημερολόγιο επισκέψεων</a><a href="/visits/new">+ Νέα επίσκεψη</a><a href="/visits/publish">Ενημέρωση Επαρχίας</a><a href="/visits/report">Αναφορά PDF</a><div class="navdrop-sep"></div><a href="/reps">Εκπρόσωποι ΜΔ</a><a href="/visits/import-data">Εισαγωγή από «Επιστολές Γραμματείας»</a></div></details><a href="/directory">📇 Κατάλογος</a><details class="navdrop"><summary>Μητρώα <span class="caret">▾</span></summary><div class="navdrop-menu"><a href="/directory">📇 Κατάλογος (Επαρχίες &amp; Στοές)</a><div class="navdrop-sep"></div><a href="/members">Μητρώο Μελών</a><a href="/lodges">Συμβολικές Στοές</a><a href="/provinces">Επαρχιακές Μεγάλες Στοές</a><div class="navdrop-sep"></div><a href="/epeteirida">Επετηρίδα</a></div></details><details class="navdrop"><summary>Διαχείριση <span class="caret">▾</span></summary><div class="navdrop-menu"><a href="/users">Πρόσβαση</a><a href="/drive">Google Drive</a><a href="/settings">Ρυθμίσεις</a><div class="navdrop-sep"></div><a href="https://claude.ai/artifact/DJ4jLfXEiCy4YyK8Joedqk" target="_blank" rel="noopener">Επιστολές Γραμματείας ↗</a></div></details>' if user['role']=='admin' else ''}{actor_link}<a href="/logout">Έξοδος</a></nav></header>{NAV_JS}'''
    return HTMLResponse(f'''<!doctype html><html lang="el"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{esc(title)}</title><style>{CSS}</style></head><body>{nav}<main class="wrap">{_notif_html(user)}{body}</main>{TABLE_JS}</body></html>''')
